class VersionedStore<T extends { readonly id: string; readonly version: number }> {
  readonly #rows = new Map<string, T>();
  save(next: T): string {
    const found = this.#rows.get(next.id)?.version ?? 0;
    if (found !== next.version - 1) return `stale (found ${found})`;
    this.#rows.set(next.id, next);
    return `saved v${next.version}`;
  }
}

