interface Captured { readonly status: "captured"; readonly amount: number; readonly refunded: number }
interface Refunded { readonly status: "refunded"; readonly amount: number }
type Outcome = Captured | Refunded | { readonly problem: "nothing" } | { readonly problem: "exceeds"; readonly remaining: number };

function applyRefund(payment: Captured, amount: number): Outcome {
  if (amount === 0) return { problem: "nothing" };
  const left = payment.amount - payment.refunded;
  if (amount > left) return { problem: "exceeds", remaining: left };
  if (amount === left) return { status: "refunded", amount: payment.amount };
  return { ...payment, refunded: payment.refunded + amount };
}

const show = (o: Outcome): string =>
  "problem" in o ? (o.problem === "exceeds" ? `exceeds ${o.remaining}` : o.problem) : o.status === "captured" ? `captured ${o.refunded}` : o.status;

const payment: Captured = { status: "captured", amount: 2020000, refunded: 0 };
const partial = applyRefund(payment, 320000);
const next = "status" in partial && partial.status === "captured" ? partial : payment;
console.log([partial, applyRefund(next, 2000000), applyRefund(next, 1700000), applyRefund(next, 0)].map(show).join(" | "));

