interface Transaction { readonly memo: string; readonly entries: readonly [Entry, ...Entry[]] }

function transaction(memo: string, entries: readonly [Entry, ...Entry[]]): Transaction {
  const total = (side: Entry["side"]) => entries.filter((e) => e.side === side).reduce((sum, e) => sum + e.amount, 0);
  if (total("debit") !== total("credit")) throw new RangeError(`unbalanced transaction "${memo}"`);
  return Object.freeze({ memo, entries });
}

