interface Entry { readonly account: string; readonly side: "debit" | "credit"; readonly amount: number }
interface Transaction { readonly memo: string; readonly entries: readonly Entry[] }

function balances(ledger: readonly Transaction[]): readonly (readonly [string, number])[] {
  const totals = new Map<string, number>();
  for (const entry of ledger.flatMap((t) => t.entries)) {
    const signed = entry.side === "debit" ? entry.amount : -entry.amount;
    totals.set(entry.account, (totals.get(entry.account) ?? 0) + signed);
  }
  return [...totals].sort(([a], [b]) => a.localeCompare(b));
}

const ledger: Transaction[] = [
  { memo: "payment", entries: [{ account: "bank", side: "debit", amount: 2020000 }, { account: "sales", side: "credit", amount: 2020000 }] },
  { memo: "refund", entries: [{ account: "refunds", side: "debit", amount: 320000 }, { account: "bank", side: "credit", amount: 320000 }] },
];
const result = balances(ledger);
const total = result.reduce((sum, [, amount]) => sum + amount, 0);
console.log(result.map(([account, amount]) => `${account}:${amount}`).join(" "), `total:${total}`);
